/** Prototype controller. All AI and admin outcomes are simulated and kept in memory. No credentials are persisted or transmitted. */
import {createWorld} from './scene.js';
const $=s=>document.querySelector(s),surface=$('#surface'),modal=$('#modal');
const state={stage:'start',smashed:false,busy:false,configured:false,provider:'OpenAI',model:'示例模型',page:'scene',reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,messages:[],request:null,question:'',proposal:null,version:1,published:'让探索成为个人网站的一部分。',records:[],scope:'全站公开内容',returnPage:'home'};
const projects=[{id:'mars',name:'远行手记',kind:'交互网站 / 设计示例',num:'01',art:'MARS',desc:'把一次短暂的探索，变成认识一个人的入口。',body:'这是一份个人站设计示例：访客可以在火星上打造工具、发现宝箱，也可以直接阅读内容。探索完成后，模型配置化作一张船票。',sections:[['想解决的问题','如何让个人网站有记忆点，同时让只想看作品的人不用学习游戏规则。'],['交互取舍','两条入口共享同一个内容站。场景服务于探索；项目与文章采用稳定的阅读布局；问答随时可以收起。'],['状态与边界','当前为可操作原型。模型验证、AI 回答与管理发布均为模拟；尚无真实业务后端。']]},{id:'index',name:'线索索引',kind:'知识阅读工具 / 概念示例',num:'02',art:'INDEX',desc:'从一个问题，找到值得读的原文。',body:'这是用于演示项目详情与引用联动的虚构概念项目，不是站长已完成的真实经历或成果。',sections:[['概念','将零散笔记整理为可追溯的主题索引，让问题与出处相连。'],['设计范围','阅读、主题查找和来源跳转；本原型只演示公开示例内容，不连接个人知识库。'],['尚待验证','真实检索质量、资料维护成本和模型评估需要在实现阶段验证。']]}];
const articles=[{id:'explore',title:'让探索有意义，而不挡住阅读',date:'设计手记 · 01',summary:'每一个可玩的动作，都应该给访客一个继续的理由。',parts:[['探索的回报','火星上，铲子通向宝箱，宝箱通向船票。动作会改变接下来的体验，而不只是播放一个动画。'],['保留另一条路','有些人愿意探索，有些人只想看项目。砸炉与直接浏览保留同一个目的地，让两种访客都能按自己的节奏前进。'],['把舞台留给内容','进入文章后，镜头停止追逐指针。正文、章节和来源承担主要工作；场景在需要时再回来。']]},{id:'sources',title:'一个回答，也应该有来路',date:'设计手记 · 02',summary:'答案的价值，不只在于说得像，还在于能找到依据。',parts:[['从公开材料开始','问答只使用获准公开的博客、项目和个人介绍。没有资料支持的问题，应明确说明不知道。'],['引用是一条返回路径','回答中的引用应打开对应文章或项目。访客看完后可以回到对话，保留问题与上下文。'],['配置由访客选择','访客选择厂商、模型并提供自己的 API Key。费用与处理方式需清楚说明，普通阅读不依赖配置。']]},{id:'boundaries',title:'给 Agent 一条清楚的边界',date:'设计手记 · 03',summary:'先给出具体变更，再决定是否执行。',parts:[['从提案开始','站长 Agent 先展示目标、依据、修改前后内容与影响页面。发送消息不等于授权发布。'],['确认对应一个版本','如果目标内容变化，旧提案需要重新检查。取消不会写入，重复确认不应重复执行。'],['把结果说清楚','保存、发布和问答来源更新是不同的步骤。某一步失败时，说明真实状态，再提供恢复路径。']]}];
let world,storyTimer,flightTimer,configTimer,toastTimer;
try{world=createWorld($('#world'),()=>{if(state.page==='scene'&&!state.busy)act(state.stage==='start'?'forge':state.stage==='shovel'?'dig':'configure')})}catch{ $('#scene').insertAdjacentHTML('beforeend','<div class="error-screen">场景暂时无法加载。下方操作仍可完成探索，也可以直接浏览主站。</div>') }
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function stopPending(){clearTimeout(storyTimer);clearTimeout(flightTimer);state.busy=false}
function showPage(page){if(modal.open)modal.close();state.page=page;surface.hidden=page==='scene';$('#game').hidden=page!=='scene';$('#flight').hidden=true;world?.setActive(page==='scene');document.body.classList.toggle('reading',page!=='scene');window.scrollTo(0,0)}
function navigate(route){const next='#/'+route;if(location.hash===next)renderRoute();else location.hash=next}
function chrome(tab){return `<div class="subnav">${[['home','概览'],['projects','项目'],['articles','文章'],['about','关于'],['contact','联系']].map(([id,label])=>`<button class="chip ${tab===id?'active':''}" data-route="${id}">${label}</button>`).join('')}</div>`}
function footer(){return '<footer class="footer"><span>远行手记 / FIELDNOTES · 内容均为设计示例</span><div><button data-action="scene">重返火星</button> · <button data-route="admin">站长工作台 · 演示</button></div></footer>'}
function projectCard(p){return `<button class="project" data-route="project/${p.id}"><div class="project-art ${p.id==='index'?'space':'mars-art'}"><span>${p.art}</span><i class="orbit"></i><small>0${p.num} / CONCEPT</small></div><div class="project-info"><div><h3>${p.name}</h3><p>${p.kind}</p></div><span>↗</span></div></button>`}
function articleRows(list){return list.length?list.map((a,i)=>`<button class="article-row" data-route="article/${a.id}"><span>0${i+1}</span><h3>${a.title}</h3><span class="date">${a.date}</span><span>↗</span></button>`).join(''):'<p class="empty">没有匹配内容。换个关键词试试，或查看全部文章。</p>'}
function home(tab='home'){showPage(tab);surface.innerHTML=`<div class="surface-head"><div><span class="eyebrow">EARTH / FIELDNOTES</span><h1>${tab==='projects'?'一些正在发生的想法。':tab==='articles'?'把想法，写下来。':'落地之后，<br>继续好奇。'}</h1></div><div><p>这里收集作品、文字，以及它们背后的思考。<br>你可以慢慢看，也可以带着问题来。</p><button class="subtle" data-action="ai">与本站 AI 聊聊 ↗</button></div></div>${chrome(tab)}${tab!=='articles'?`<div class="section-label"><span>SELECTED PROJECTS / 精选项目</span><span>02 · 示例</span></div>${tab==='projects'?'<input class="search" id="project-search" placeholder="查找项目名称或简介" aria-label="查找项目">':''}<div class="project-grid" id="project-list">${projects.map(projectCard).join('')}</div>`:''}${tab!=='projects'?`<div class="section-label"><span>NOTES / 文章</span><span>03 · 示例</span></div><input class="search" id="search" placeholder="查找文章标题或关键词" aria-label="查找文章"><div id="article-list">${articleRows(articles)}</div>`:''}${footer()}`;$('#project-search')?.addEventListener('input',e=>{const found=projects.filter(p=>(p.name+p.desc+p.body).includes(e.target.value.trim()));$('#project-list').innerHTML=found.length?found.map(projectCard).join(''):'<p>没有匹配项目。试试其他关键词。</p>'});$('#search')?.addEventListener('input',e=>{$('#article-list').innerHTML=articleRows(articles.filter(a=>(a.title+a.summary+a.parts.flat().join('')).includes(e.target.value.trim())))})}
function detail(type,id){const item=(type==='project'?projects:articles).find(x=>x.id===id);if(!item){showPage('not-found');surface.innerHTML='<h1>这条线索暂时不存在。</h1><button class="primary" data-route="home">返回主站</button>';return}showPage(type);surface.innerHTML=`<button class="back" data-route="${type==='project'?'projects':'articles'}">← 返回${type==='project'?'项目':'文章'}</button><div class="body-copy"><span class="eyebrow">${type==='project'?'PROJECT':'NOTE'} / 内容示例</span><h1>${item.name||item.title}</h1><p>${item.desc||item.summary}</p><div class="callout">这是原型设计内容，不代表站长的真实经历、项目成果或已发表文章。</div>${item.body?`<p>${item.body}</p>`:''}${type==='project'&&id==='mars'&&state.version>1?`<div class="callout">工作台更新 · 模拟 v${state.version}<p>${esc(state.published)}</p></div>`:''}<div class="toc">${(item.sections||item.parts).map((p,i)=>`<button data-section="section-${i}">${String(i+1).padStart(2,'0')} ${p[0]}</button>`).join('')}</div>${(item.sections||item.parts).map(([h,p],i)=>`<section id="section-${i}"><h2>${h}</h2><p>${p}</p></section>`).join('')}<button class="primary" data-action="ask-context" data-context="${type==='project'?'项目：'+item.name:'文章：'+item.title}">问问 AI，关于这${type==='project'?'个项目':'篇文章'} ↗</button>${state.messages.length?'<button class="subtle" data-route="chat">返回刚才的对话 ↗</button>':''}</div>${footer()}`}
function about(){showPage('about');surface.innerHTML=`${chrome('about')}<div class="body-copy"><span class="eyebrow">ABOUT / 待本人补充</span><h1>不止于作品，<br>也关于做作品的人。</h1><p>这个位置留给你的真实介绍：你关注什么、正在做什么，以及愿意和别人讨论什么。</p><div class="callout">公开姓名、职业、履历与联系方式尚未提供。原型不会代你编造经历。</div><h2>这份网站的表达</h2><p>保留好奇，做出东西，记录过程。火星是一个故事入口，文章和项目承载真实内容。</p><h2>未来可以放在这里</h2><p>一句话自我介绍、当前关注的主题、可核对的项目经历与本人批准的联系渠道。</p><button class="primary" data-action="ai">问问本站 AI ↗</button></div>${footer()}`}
function contact(){showPage('contact');surface.innerHTML=`${chrome('contact')}<div class="body-copy"><span class="eyebrow">CONTACT</span><h1>有想法，<br>也欢迎交换。</h1><p>联系邮箱与社交账号待本人提供。</p><div class="callout">原型不展示虚构邮箱，也不收集访客信息。正式内容确认后，这里会放可直接使用的联系渠道。</div><button class="primary" data-route="projects">先看看项目 ↗</button></div>${footer()}`}
function mission(){const defs={start:['01 / 找到出发的工具','靠近熔炉，做个选择。','铁料 × 1','<button class="primary" data-action="forge">打造铲子 <span>↗</span></button><button class="subtle" data-action="smash">砸炉，直接进入主站</button>'],shovel:['02 / 山坡后面有什么','铲子准备好了，去山坡后看看。','铲子 × 1','<button class="primary" data-action="dig">前往坡后挖掘 <span>↗</span></button><button class="subtle" data-action="smash">还是砸炉，去主站</button>'],chest:['03 / 一份来自远方的邀请','宝箱里，是一张尚未签发的船票。','铲子 + 宝箱','<button class="primary" data-action="configure">打开宝箱 <span>↗</span></button><button class="subtle" data-action="home">先去主站看看</button>']};const d=defs[state.stage]||defs.start;$('#step').textContent=d[0];$('#mission').textContent=d[1];$('#inventory').textContent=d[2];$('.actions').innerHTML=d[3]}
function scene(){stopPending();if(state.smashed){world?.reset();state.stage='start';state.smashed=false}showPage('scene');world?.finish('idle');mission()}
function openDialog(html){$('#dialog-content').innerHTML=html;if(!modal.open)modal.showModal();world?.setActive(false)}
function closeDialog(){clearTimeout(configTimer);modal.close();world?.setActive(state.page==='scene')}
modal.addEventListener('close',()=>{clearTimeout(configTimer);world?.setActive(state.page==='scene')});
function config(){state.returnPage=state.page;openDialog(`<div class="modal-top"><span class="eyebrow">BOARDING / 模拟配置</span><button data-action="close" aria-label="关闭配置">×</button></div><h2>签发你的星际船票</h2><p>选择同行的模型，带着问题出发。</p><div class="callout fine">演示不会连接模型。请勿输入真实 API Key；使用下方示例即可体验。</div><form id="config-form"><label for="provider">模型厂商</label><select class="field" id="provider"><option>OpenAI</option><option>Anthropic</option><option>DeepSeek</option><option>自定义兼容接口</option></select><div id="endpoint-wrap" hidden><label for="endpoint">接口地址（示例）</label><input class="field" id="endpoint" readonly value="https://example.invalid/v1"></div><label for="model">模型</label><input class="field" id="model" value="${esc(state.model)}" required placeholder="填写模型名称"><label for="demo-key">API Key（固定假值）</label><input class="field" id="demo-key" type="password" value="demo-only-not-a-real-key" readonly aria-describedby="key-help"><p class="fine" id="key-help">原型禁用真实凭据输入。正式版默认仅在本次会话使用；具体接入方式待工程方案评审。</p><label for="config-outcome">演示验证结果</label><select class="field" id="config-outcome"><option value="ok">配置有效</option><option value="invalid">Key 无效</option><option value="model">模型不可用</option><option value="quota">余额不足 / 限流</option><option value="network">网络失败</option></select><p class="config-error" id="config-error" role="alert"></p><button class="primary" id="validate" type="submit">验证配置并生成船票 ↗</button><p class="fine">正式版会发送问题和相关公开资料给所选服务，调用费用由访客账户承担。本原型无请求、无费用。</p></form>`);$('#provider').value=state.provider;$('#provider').addEventListener('change',()=>{$('#endpoint-wrap').hidden=$('#provider').value!=='自定义兼容接口'});$('#config-form').addEventListener('submit',e=>{e.preventDefault();const outcome=$('#config-outcome').value,provider=$('#provider').value,model=$('#model').value.trim();if(!model){$('#config-error').textContent='请填写模型名称。';return}$('#validate').disabled=true;$('#validate').textContent='正在验证（模拟）…';configTimer=setTimeout(()=>{if(!modal.open)return;if(outcome!=='ok'){const errors={invalid:'Key 无效（模拟）。请检查配置后重试。',model:'当前模型不可用（模拟）。请更换模型。',quota:'余额不足或请求限流（模拟）。可稍后重试，或直接浏览主站。',network:'连接失败（模拟）。探索进度已保留。'};$('#config-error').textContent=errors[outcome];$('#validate').disabled=false;$('#validate').textContent='重新验证';return}state.configured=true;state.provider=provider;state.model=model;ticket()},state.reduced?100:700)})}
function ticket(){openDialog(`<div class="modal-top"><span class="eyebrow">READY FOR DEPARTURE</span><button data-action="close" aria-label="关闭船票">×</button></div><div class="ticket"><span class="eyebrow">INTERPLANETARY BOARDING PASS</span><h2>MARS → EARTH</h2><p style="color:#705337">一张船票，很多种可能。</p><div class="ticket-info"><span>${esc(state.provider)}<br>${esc(state.model)}</span><span>SEAT 01<br>DEMO ONLY</span></div></div><p>配置已通过模拟验证。你的问题，准备好了吗？</p><button class="primary" data-action="launch">登船，前往地球 ↗</button><button class="subtle" data-action="land">直接打开对话</button>`)}
function launch(){closeDialog();stopPending();showPage('scene');world?.action('launch');world?.setActive(true);state.page='flight';$('#mission').textContent='已登船，准备离开火星。';$('.actions').innerHTML='<button class="primary" data-action="land">跳过飞行，打开对话 ↗</button>';flightTimer=setTimeout(()=>{$('#flight').hidden=false;$('#flight-title').textContent='穿过大气层，向地球降落。';world?.setActive(false);flightTimer=setTimeout(()=>navigate('chat'),state.reduced?100:4000)},state.reduced?100:1400)}
function chat(){if(!state.configured){if(state.page==='scene')config();else{home();config()}return}showPage('chat');surface.innerHTML=`<div class="chat-layout"><aside class="chat-aside"><span class="eyebrow">EARTH / ARRIVAL</span><strong>随时可以换条路线。</strong><button data-action="recover">↙ 回收飞船 · 浏览主站</button><button data-action="configure">模型配置</button><button data-action="clear-key">清除本次配置</button><button data-action="new-chat">新对话</button><p class="fine">${esc(state.provider)}<br>${esc(state.model)}<br>模拟连接 · 未调用模型</p></aside><div><div class="chat-head"><div><span class="eyebrow">ASK FIELDNOTES</span><h1>降落了。聊点什么？</h1></div><button class="chip" data-action="scope">${esc(state.scope)}</button></div><div id="messages" class="messages"></div><div id="suggestions"></div><form class="composer" id="chat-form"><textarea id="question" aria-label="输入问题" placeholder="问问项目、博客，或关于我的信息…" maxlength="2000">${esc(state.question)}</textarea><button type="submit" id="send">发送 ↗</button></form><div id="chat-status" class="chat-status" role="status"></div><p class="fine">模拟问答 · 仅引用本站示例内容，不代表真实个人经历。</p><details class="test-controls"><summary>演示异常状态</summary><select id="chat-outcome" class="field" aria-label="模拟回答结果"><option value="auto">按问题匹配示例</option><option value="empty">资料不足</option><option value="error">服务失败</option><option value="rate">限流</option></select></details></div></div>`;renderMessages();$('#chat-form').addEventListener('submit',e=>{e.preventDefault();ask($('#question').value)});$('#question').addEventListener('input',e=>state.question=e.target.value);$('#question').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#chat-form').requestSubmit()}})}
function renderMessages(){const node=$('#messages');if(!node)return;node.innerHTML=state.messages.length?state.messages.map(m=>`<div class="message ${m.role}"><small>${m.role==='user'?'你':'本站 AI · 模拟'}</small>${esc(m.text).replace(/\n/g,'<br>')}${(m.sources||[]).map(s=>`<button class="source" data-route="${s.route}">${s.label} ↗</button>`).join('')}</div>`).join(''):'<div class="chat-empty"><h2>每一个问题，<br>都可以是一段旅程的开始。</h2><p>先从这些公开的内容聊起。</p></div>';$('#suggestions').innerHTML=state.messages.length?'':`<div class="suggestions"><button data-question="介绍一下远行手记">介绍一下远行手记</button><button data-question="文章里怎样看待 AI 引用？">聊聊 AI 的引用</button><button data-question="站长有怎样的经历？">关于站长的经历</button></div>`}
function stopChat(){if(state.request){clearTimeout(state.request);state.request=null;state.messages.push({role:'assistant',text:'已停止生成。没有产生完整回答。'});renderMessages();if($('#send')){$('#send').disabled=false;$('#send').textContent='发送 ↗'}if($('#chat-status'))$('#chat-status').textContent='已停止；问题已保留。'}}
function ask(question){if(state.request)return;const q=question.trim();if(!q)return;state.question=q;const result=$('#chat-outcome')?.value||'auto';if(state.scope!=='全站公开内容'&&/其他项目|全站|所有项目/.test(q)){openDialog('<h2>切换到全站问答？</h2><p>这个问题超出了当前内容范围。切换后会查找本站全部公开示例。</p><button class="primary" data-action="scope-confirm">切换并继续提问</button><button class="subtle" data-action="close">保留当前范围</button>');return}state.messages.push({role:'user',text:q});renderMessages();$('#send').disabled=true;$('#chat-status').innerHTML='正在查找公开示例… <button data-action="stop-chat">停止生成</button>';state.request=setTimeout(()=>{state.request=null;if(result==='error'||result==='rate'){if($('#chat-status'))$('#chat-status').textContent=result==='error'?'服务失败（模拟）。问题已保留，可再次发送或调整配置。':'请求限流（模拟）。问题已保留，请稍后重试。';if($('#send'))$('#send').disabled=false;return}let text,sources=[];if(result==='empty'||/经历|姓名|收入|工作|年龄|住址|公司/.test(q)){text='本站尚未提供可核对的个人资料，我不能据此编造站长的经历。你可以先查看项目设计示例，或等站长补充公开介绍。';sources=[{label:'关于 · 待补充',route:'about'}]}else if(/引用|来源|博客|文章/.test(q)){text='这份示例强调：回答应来自获准公开的材料，引用要能打开原文；资料不足时明确说明不知道。打开下面的文章可以核对这些设计约定。';sources=[{label:'一个回答，也应该有来路',route:'article/sources'}]}else if(/Agent|管理|发布/.test(q)){text='站长管理演示采用“先提案，再确认”：展示具体差异，确认对应内容版本，分别报告保存、发布和来源更新。访客问答不能执行管理写入。';sources=[{label:'给 Agent 一条清楚的边界',route:'article/boundaries'}]}else if(/远行|火星|网站|项目|探索|铲子/.test(q)){text='远行手记是这份个人站原型的设计名称。它用火星探索串起打造铲子、挖宝、配置模型与飞往地球的旅程，也允许砸炉或直接浏览。它目前是演示原型，不是已上线的真实 AI 产品。';sources=[{label:'远行手记 · 项目示例',route:'project/mars'},{label:'让探索有意义',route:'article/explore'}]}else{text='这份原型没有找到能支持该问题的示例资料。你可以问远行手记的设计、文章中的引用原则，或站长 Agent 的确认流程。';}state.messages.push({role:'assistant',text,sources});state.question='';renderMessages();if($('#question'))$('#question').value='';if($('#send'))$('#send').disabled=false;if($('#chat-status'))$('#chat-status').textContent='回答完成 · 预设内容模拟';},1200)}
function admin(){showPage('admin');surface.innerHTML=`<div class="surface-head"><div><span class="eyebrow">OWNER STUDIO / 演示</span><h1>把想法，整理成更新。</h1></div><p>模拟站长工作台，不代表已登录或具有真实发布权限。</p></div><div class="subnav"><button class="chip" data-route="home">← 返回主站</button><button class="chip" data-action="records">执行与版本记录</button><button class="chip" data-action="admin-expire">模拟登录过期</button></div><div class="admin-grid"><section class="panel"><h2>这次想改什么？</h2><label for="admin-kind">内容目标</label><select class="field" id="admin-kind"><option value="project">更新项目介绍</option><option value="article">新建文章草稿</option></select><textarea id="admin-input" class="field" aria-label="更新要求" placeholder="例如：强调访客可以直接浏览，不必完成探索。">强调访客可以直接浏览，不必完成探索。</textarea><p class="fine">仅使用提供的材料；原型按固定规则生成示例提案。</p><button class="primary" data-action="propose">生成修改提案 ↗</button></section><section class="panel" id="proposal"><span class="eyebrow">REVIEW BEFORE PUBLISH</span><h2>先看差异，再决定。</h2><p>当前项目版本 v${state.version}</p><p>${esc(state.published)}</p><p class="fine">没有确认，就不会发生模拟发布。</p></section></div>${footer()}`}
function propose(){const input=$('#admin-input').value.trim(),kind=$('#admin-kind').value;if(!input){toast('请先提供修改目标或材料。');return}if(/删除|发邮件|改代码|购买/.test(input)){toast('该操作不在首版内容管理范围内。');return}state.proposal={kind,before:kind==='article'?'（尚无草稿）':state.published,after:kind==='article'?'示例草稿：'+input:'让探索成为个人网站的一部分。访客也可随时直接浏览项目与文章。\n修改依据：'+input,version:state.version,status:'pending'};proposalView()}
function proposalView(){const p=state.proposal;if(!p)return;$('#proposal').innerHTML=`<span class="eyebrow">PROPOSAL / v${p.version}</span><h2>${p.kind==='article'?'新建文章草稿':'更新「远行手记」介绍'}</h2><p class="fine">影响：示例内容、主站展示与问答来源（均模拟）</p><div class="diff before"><small>修改前</small><br>${esc(p.before)}</div><div class="diff after"><small>修改后</small><br>${esc(p.after).replace(/\n/g,'<br>')}</div><label for="publish-mode">演示执行结果</label><select class="field" id="publish-mode"><option value="ok">保存、发布、来源更新成功</option><option value="partial">发布成功，来源更新失败</option><option value="failed">保存失败</option><option value="conflict">内容版本冲突</option><option value="unknown">结果待核实</option></select><div class="actions"><button class="primary" data-action="publish">确认${p.kind==='article'?'保存草稿':'发布'} · 模拟</button><button class="subtle" data-action="cancel-proposal">取消</button></div>`}
function publish(){const p=state.proposal;if(!p||p.status!=='pending')return;const mode=$('#publish-mode').value;if(mode==='conflict'||p.version!==state.version){p.status='stale';$('#proposal').innerHTML='<h2>提案已失效</h2><p>目标内容版本变化，请重新生成差异。旧确认不能继续使用。</p>';return}p.status='executing';$('#proposal').innerHTML='<h2>正在执行（模拟）…</h2><p>此期间不会重复提交。</p>';setTimeout(()=>{if(state.page!=='admin'||state.proposal!==p)return;if(mode==='failed'){p.status='failed';$('#proposal').innerHTML='<h2>保存失败（模拟）</h2><p>没有发布任何修改。</p><button class="primary" data-action="retry-proposal">重新检查提案</button>';return}if(mode==='unknown'){p.status='unknown';$('#proposal').innerHTML='<h2>结果待核实</h2><p>模拟连接中断。请核对本次操作，不要重复发布。</p><button class="primary" data-action="verify-publish">核实本次结果</button>';return}finishPublish(mode)},700)}
function finishPublish(mode){const p=state.proposal;if(!p)return;if(p.kind==='project'){state.records.push({version:state.version,text:state.published});state.published=p.after;state.version++}p.status='done';if($('#proposal'))$('#proposal').innerHTML=`<span class="eyebrow">EXECUTION / 模拟结果</span><h2>${p.kind==='article'?'草稿已保存':'内容已发布'}</h2><p>内容保存：成功<br>站点发布：${p.kind==='article'?'未执行（仅草稿）':'成功'}<br>问答来源：${p.kind==='article'?'未执行':mode==='partial'?'更新失败':'更新成功'}</p>${mode==='partial'?'<button class="primary" data-action="retry-index">重试来源更新 · 模拟</button>':''}<button class="subtle" data-action="records">查看版本记录</button>`}
function records(){openDialog(`<div class="modal-top"><h2>版本记录 · 模拟</h2><button data-action="close" aria-label="关闭记录">×</button></div><p>当前项目版本 v${state.version}</p>${state.records.length?state.records.map((r,i)=>`<div class="diff before"><strong>v${r.version}</strong><p>${esc(r.text)}</p><button class="subtle" data-restore="${i}">预览恢复差异</button></div>`).join(''):'<p>暂无已发布的历史版本。先执行一次项目更新。</p>'}`)}
function restore(i){const r=state.records[i];if(!r)return;openDialog(`<h2>恢复到 v${r.version}？</h2><p>恢复会生成新版本，并覆盖当前这段项目介绍。</p><div class="diff before">当前：${esc(state.published)}</div><div class="diff after">恢复为：${esc(r.text)}</div><button class="primary" data-confirm-restore="${i}" data-version="${state.version}">确认恢复 · 模拟</button><button class="subtle" data-action="close">取消</button>`)}
function renderRoute(){stopChat();stopPending();const route=location.hash.slice(2)||'scene';if(route==='scene')scene();else if(['home','projects','articles'].includes(route))home(route);else if(route==='about')about();else if(route==='contact')contact();else if(route==='chat')chat();else if(route==='admin')admin();else if(route.startsWith('project/'))detail('project',route.split('/')[1]);else if(route.startsWith('article/'))detail('article',route.split('/')[1]);else{showPage('404');surface.innerHTML='<h1>这条路线还未被发现。</h1><button class="primary" data-route="home">返回主站</button>'}}
function act(action,b){switch(action){case'home':navigate('home');break;case'scene':navigate('scene');break;case'forge':if(state.busy||state.stage!=='start')return;state.busy=true;world?.action('forge');$('#mission').textContent='炉火正旺，铲子即将完成。';$('.actions').innerHTML='<button class="primary" disabled>打造中…</button>';storyTimer=setTimeout(()=>{world?.finish('forge');state.stage='shovel';state.busy=false;mission();toast('获得铲子。山坡后有一点微光。')},state.reduced?100:1800);break;case'dig':if(state.busy||state.stage!=='shovel')return;state.busy=true;world?.go('dig');$('#mission').textContent='往山坡后走，寻找松动的土壤。';$('.actions').innerHTML='<button class="primary" disabled>前往挖掘点…</button>';storyTimer=setTimeout(()=>{world?.action('dig');$('#mission').textContent='土层下面，露出一角金属。';storyTimer=setTimeout(()=>{world?.finish('dig');state.stage='chest';state.busy=false;mission()},state.reduced?100:1500)},state.reduced?100:2200);break;case'smash':if(state.busy)return;state.busy=true;state.smashed=true;world?.action('smash');$('#mission').textContent='换一条路，也能抵达。';$('.actions').innerHTML='<button class="primary" disabled>正在搬起熔炉…</button>';storyTimer=setTimeout(()=>{navigate('home');toast('已抵达主站。AI 入口一直为你保留。')},state.reduced?100:2300);break;case'ai':state.scope='全站公开内容';state.configured?navigate('chat'):config();break;case'configure':config();break;case'close':closeDialog();break;case'launch':launch();break;case'land':closeDialog();navigate('chat');break;case'recover':surface.classList.add('recovering');storyTimer=setTimeout(()=>{surface.classList.remove('recovering');navigate('home');toast('飞船已回收，本次对话仍然保留。')},state.reduced?0:500);break;case'clear-key':state.configured=false;stopChat();home();toast('本次模拟配置已清除。');break;case'new-chat':stopChat();state.messages=[];state.question='';chat();break;case'ask-context':state.scope=b.dataset.context;state.configured?navigate('chat'):config();break;case'scope':openDialog(`<h2>问答范围</h2><p>当前：${esc(state.scope)}</p><button class="primary" data-action="scope-all">切换到全站公开内容</button><button class="subtle" data-action="close">保留当前范围</button>`);break;case'scope-all':state.scope='全站公开内容';closeDialog();chat();break;case'scope-confirm':state.scope='全站公开内容';closeDialog();chat();ask(state.question);break;case'stop-chat':stopChat();break;case'propose':propose();break;case'publish':publish();break;case'cancel-proposal':state.proposal=null;$('#proposal').innerHTML='<h2>提案已取消</h2><p>没有发生内容变更或发布。</p>';break;case'retry-proposal':state.proposal.status='pending';proposalView();break;case'verify-publish':finishPublish('ok');break;case'retry-index':$('#proposal').innerHTML='<h2>来源更新成功 · 模拟</h2><p>内容保存、站点发布与问答来源均已完成。</p><button class="subtle" data-action="records">查看版本记录</button>';break;case'records':records();break;case'admin-expire':state.proposal=null;openDialog('<h2>登录已过期 · 模拟</h2><p>执行已阻止。重新进入演示不会自动发布。</p><button class="primary" data-action="admin-login">重新进入演示</button><button class="subtle" data-action="close">取消</button>');$('#proposal').innerHTML='<h2>请重新进入演示</h2><p>旧提案不再可执行。</p>';break;case'admin-login':closeDialog();admin();break}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.route)navigate(b.dataset.route);if(b.dataset.action)act(b.dataset.action,b);if(b.dataset.move)world?.move(b.dataset.move);if(b.dataset.question){$('#question').value=b.dataset.question;ask(b.dataset.question)}if(b.dataset.section)document.getElementById(b.dataset.section)?.scrollIntoView({behavior:state.reduced?'instant':'smooth',block:'start'});if(b.dataset.restore!==undefined)restore(Number(b.dataset.restore));if(b.dataset.confirmRestore!==undefined){if(Number(b.dataset.version)!==state.version){toast('当前版本已改变，请重新检查。');return}const old=state.records[Number(b.dataset.confirmRestore)];state.records.push({version:state.version,text:state.published});state.published=old.text;state.version++;closeDialog();admin();toast('已恢复为新版本 v'+state.version+'（模拟）。')}});
$('#motion').addEventListener('click',()=>{state.reduced=!state.reduced;document.body.classList.toggle('reduced',state.reduced);$('#motion').setAttribute('aria-pressed',String(state.reduced));world?.reduce(state.reduced);toast(state.reduced?'已减少动效。核心流程仍可使用。':'已恢复动效。')});document.body.classList.toggle('reduced',state.reduced);$('#motion').setAttribute('aria-pressed',String(state.reduced));window.addEventListener('hashchange',renderRoute);renderRoute();
// Agent-facing read-back shares the same prototype state; never exposes credentials.
const mc=document.modelContext;if(mc?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'read_journey_state',title:'Read prototype journey',description:'Read current visible Mars prototype progress; no credentials or real AI.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected empty object');return {page:state.page,stage:state.stage,configured:state.configured,simulated:true,world:world?.snapshot()}}},{name:'navigate_prototype',title:'Navigate prototype',description:'Navigate to a visible prototype page. Does not publish content or configure a real model.',inputSchema:{type:'object',properties:{page:{type:'string',enum:['scene','home','projects','articles','about','contact','admin']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!input||Object.keys(input).length!==1||!['scene','home','projects','articles','about','contact','admin'].includes(input.page))throw Error('Invalid page');navigate(input.page);await new Promise(r=>setTimeout(r,30));return{page:state.page,simulated:true}}}]){try{Promise.resolve(mc.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}}
